package com.ibm.cobolisfun.jsonparse.model;

import com.fasterxml.jackson.annotation.JsonProperty;
import lombok.Data;
import lombok.NoArgsConstructor;
import lombok.AllArgsConstructor;

import java.math.BigDecimal;

@Data
@NoArgsConstructor
@AllArgsConstructor
public class Transaction {

    /** Maps to COBOL: tx-uid  pic 99999 */
    @JsonProperty("tx-uid")
    private Integer txUid;

    /** Maps to COBOL: tx-item-desc  pic x(50) */
    @JsonProperty("tx-item-desc")
    private String txItemDesc;

    /** Maps to COBOL: tx-item-uid  pic AA/9999B99 */
    @JsonProperty("tx-item-uid")
    private String txItemUid;

    /**
     * Maps to COBOL: tx-price  pic $$$9.99
     * COBOL JSON PARSE used NAME clause:  name tx-price is 'tx-priceinUS$'
     * so the JSON key is 'tx-priceinUS$' even though the COBOL field is tx-price.
     */
    @JsonProperty("tx-priceinUS$")
    private BigDecimal txPrice;

    /** Maps to COBOL: tx-comment  pic n(20) */
    @JsonProperty("tx-comment")
    private String txComment;
}

