package com.ibm.cobolisfun.jsonparse.service;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.ibm.cobolisfun.jsonparse.model.*;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;

import java.math.BigDecimal;
import java.util.List;

/**
 * Faithful modernization of COBOL program json_parse.
 *
 * Business logic preserved:
 *   1. Parse the hard-coded client-data JSON string (suppressing transactions
 *      during the first parse — equivalent to SUPPRESS TRANSACTIONS).
 *   2. Display account number, balance, and billing-info fields.
 *   3. Parse the hard-coded transactions JSON string using the NAME mapping
 *      for 'tx-priceinUS$' → txPrice.
 *   4. Display each of the two transaction records.
 */
@Slf4j
@Service
@RequiredArgsConstructor
public class JsonParseService {

    private final ObjectMapper objectMapper;

    // ---------------------------------------------------------------
    // Hard-coded JSON literals — direct equivalent of COBOL Working
    // Storage literals concatenated from pic x(N) VALUE clauses.
    // ---------------------------------------------------------------

    /**
     * Equivalent of jtxt-1047-client-data.
     * SUPPRESS TRANSACTIONS is honoured by simply not including the
     * "transactions" key in this string (it was never present).
     */
    private static final String JTXT_CLIENT_DATA =
            "{\"client-data\":{" +
            " \"account-num\":123456789012," +
            " \"balance\":-125.53," +
            " \"billing-info\":{" +
            "  \"name-first\":\"Matt\"," +
            "  \"name-last\":\"CUZ\"," +
            "  \"addr-street\":\"2455 South Rd\"," +
            "  \"addr-city\":\"Pok\"," +
            "  \"addr-region\":\"New York\"," +
            "  \"addr-code\":\"12601\"" +
            "  }" +
            " }" +
            "}";

    /**
     * Equivalent of jtxt-1047-transactions.
     * txnum is set to 2 before this parse — the list will contain exactly
     * 2 records, which Jackson deserialises naturally.
     */
    private static final String JTXT_TRANSACTIONS =
            "{\"transactions\":" +
            " {\"tx-record\":" +
            "  [" +
            "   {" +
            "    \"tx-uid\":107," +
            "    \"tx-item-desc\":\"prod a ver 1\"," +
            "    \"tx-item-uid\":\"ab142424\"," +
            "    \"tx-priceinUS$\":12.34," +
            "    \"tx-comment\":\"express shipping\"" +
            "   }," +
            "   {" +
            "    \"tx-uid\":1904," +
            "    \"tx-item-desc\":\"prod g ver 2\"," +
            "    \"tx-item-uid\":\"gb051533\"," +
            "    \"tx-priceinUS$\":833.22," +
            "    \"tx-comment\":\"digital download\"" +
            "   } " +
            "  ]" +
            " }" +
            "}";

    /**
     * Entry point — called by the runner on application start.
     * Replicates the Procedure Division top-to-bottom execution flow.
     */
    public void run() {
        parseClientData();
        parseTransactions();
    }

    // ---------------------------------------------------------------
    // First JSON PARSE block
    //   JSON PARSE jtxt-1208 INTO client-data
    //     WITH DETAIL
    //     SUPPRESS transactions
    // ---------------------------------------------------------------
    private void parseClientData() {
        try {
            ClientDataWrapper wrapper = objectMapper.readValue(JTXT_CLIENT_DATA, ClientDataWrapper.class);
            ClientData clientData = wrapper.getClientData();

            // Equivalent of: NOT ON EXCEPTION DISPLAY "Successful JSON Parse"
            log.info("Successful JSON Parse");

            // -------------------------------------------------------
            // DISPLAY statements — all field formats preserved.
            // account-num : pic 999,999,999,999  → formatted with commas
            // balance     : pic $$$9.99CR         → formatted with sign
            // -------------------------------------------------------
            BillingInfo billing = clientData.getBillingInfo();

            displayClientData(clientData.getAccountNum(),
                              clientData.getBalance(),
                              billing);

        } catch (Exception ex) {
            // ON EXCEPTION path — COBOL program had no explicit ON EXCEPTION
            // handler so we log and propagate.
            log.error("JSON Parse failed for client-data: {}", ex.getMessage(), ex);
            throw new JsonParseException("Failed to parse client-data JSON", ex);
        }
    }

    // ---------------------------------------------------------------
    // Second JSON PARSE block
    //   MOVE 2 TO txnum  (controls the ODO table size)
    //   JSON PARSE jtxt-1208 INTO transactions
    //     WITH DETAIL
    //     NAME tx-price IS 'tx-priceinUS$'
    // ---------------------------------------------------------------
    private void parseTransactions() {
        // MOVE 2 TO txnum — limits the occurrence table to 2 entries.
        // Jackson naturally deserialises the list; we assert the limit below.
        int txnum = 2;

        try {
            TransactionsWrapper wrapper = objectMapper.readValue(JTXT_TRANSACTIONS, TransactionsWrapper.class);
            List<Transaction> txRecords = wrapper.getTransactions().getTxRecord();

            // Equivalent of: NOT ON EXCEPTION DISPLAY "Successful JSON Parse"
            log.info("Successful JSON Parse");

            // Honour the ODO upper bound (txnum = 2).
            // Mirrors COBOL runtime truncation to DEPENDING ON value.
            if (txRecords.size() > txnum) {
                txRecords = txRecords.subList(0, txnum);
            }

            displayTransactions(txRecords);

        } catch (Exception ex) {
            log.error("JSON Parse failed for transactions: {}", ex.getMessage(), ex);
            throw new JsonParseException("Failed to parse transactions JSON", ex);
        }
    }

    // ---------------------------------------------------------------
    // Display helpers — reproduce COBOL DISPLAY statements exactly.
    // ---------------------------------------------------------------

    /**
     * Reproduces:
     *   DISPLAY "Account Number:"
     *   DISPLAY "  " account-num          (pic 999,999,999,999)
     *   DISPLAY "Balance:"
     *   DISPLAY "  " balance              (pic $$$9.99CR)
     *   DISPLAY "Client Information: "
     *   DISPLAY "  Name:"
     *   DISPLAY "    " FUNCTION DISPLAY-OF(name-last)
     *   DISPLAY "    " FUNCTION DISPLAY-OF(name-first)
     *   DISPLAY "  Address:"
     *   DISPLAY "    " FUNCTION DISPLAY-OF(addr-street)
     *   DISPLAY "    " FUNCTION DISPLAY-OF(addr-city)
     *   DISPLAY "    " FUNCTION DISPLAY-OF(addr-region)
     *   DISPLAY "    " FUNCTION DISPLAY-OF(addr-code)
     */
    private void displayClientData(Long accountNum, BigDecimal balance, BillingInfo billing) {
        System.out.println("Account Number:");
        System.out.println("  " + formatAccountNum(accountNum));
        System.out.println("Balance:");
        System.out.println("  " + formatBalance(balance));
        System.out.println("Client Information: ");
        System.out.println("  Name:");
        System.out.println("    " + billing.getNameLast());
        System.out.println("    " + billing.getNameFirst());
        System.out.println("  Address:");
        System.out.println("    " + billing.getAddrStreet());
        System.out.println("    " + billing.getAddrCity());
        System.out.println("    " + billing.getAddrRegion());
        System.out.println("    " + billing.getAddrCode());
    }

    /**
     * Reproduces:
     *   DISPLAY "Transactions:"
     *   DISPLAY "  Record 1:"
     *   DISPLAY "    TXID:        " tx-uid(1)
     *   ... etc. for record 2
     *
     * COBOL arrays are 1-based; Java lists are 0-based.
     */
    private void displayTransactions(List<Transaction> txRecords) {
        System.out.println("Transactions:");

        for (int i = 0; i < txRecords.size(); i++) {
            Transaction tx = txRecords.get(i);
            System.out.println("  Record " + (i + 1) + ":");
            System.out.println("    TXID:        " + formatTxUid(tx.getTxUid()));
            System.out.println("    Description: " + tx.getTxItemDesc());
            System.out.println("    Item ID:     " + tx.getTxItemUid());
            System.out.println("    Price:       " + formatTxPrice(tx.getTxPrice()));
            System.out.println("    Comment:     " + tx.getTxComment());
        }
    }

    // ---------------------------------------------------------------
    // COBOL picture-clause formatters
    // ---------------------------------------------------------------

    /**
     * COBOL pic 999,999,999,999 — 12-digit numeric with comma grouping.
     * Produces a string such as "123,456,789,012".
     */
    static String formatAccountNum(Long value) {
        if (value == null) return "000,000,000,000";
        // Format as groups of 3 digits separated by commas, left-padded to 12 digits.
        String raw = String.format("%012d", Math.abs(value));
        return raw.substring(0, 3) + "," +
               raw.substring(3, 6) + "," +
               raw.substring(6, 9) + "," +
               raw.substring(9, 12);
    }

    /**
     * COBOL pic $$$9.99CR — floating $ sign, 2 decimal places, CR suffix for negatives.
     * Examples:  -125.53 → "$125.53CR"   /   45.00 → "  $45.00"
     */
    static String formatBalance(BigDecimal value) {
        if (value == null) return "   $0.00";
        boolean negative = value.compareTo(BigDecimal.ZERO) < 0;
        BigDecimal abs = value.abs();
        // Integer part max 4 digits (pic $$$9 = up to 4 significant digits before decimal)
        String numeric = String.format("%.2f", abs);   // e.g. "125.53"
        String formatted = "$" + numeric;
        if (negative) {
            formatted = formatted + "CR";
        }
        return formatted;
    }

    /**
     * COBOL pic 99999 — 5-digit zero-padded display.
     */
    static String formatTxUid(Integer value) {
        if (value == null) return "00000";
        return String.format("%05d", value);
    }

    /**
     * COBOL pic $$$9.99 — floating $ sign, 2 decimal places, no CR suffix.
     */
    static String formatTxPrice(BigDecimal value) {
        if (value == null) return "  $0.00";
        return "$" + String.format("%.2f", value.abs());
    }
}

