package com.ibm.cobolisfun.jsonparse.service;

/**
 * Unchecked exception thrown when the JSON parse step fails,
 * equivalent to the COBOL ON EXCEPTION path of JSON PARSE.
 */
public class JsonParseException extends RuntimeException {

    public JsonParseException(String message, Throwable cause) {
        super(message, cause);
    }
}

