package com.ibm.cobolisfun.jsonparse.runner;

import com.ibm.cobolisfun.jsonparse.service.JsonParseService;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.boot.CommandLineRunner;
import org.springframework.stereotype.Component;

/**
 * Spring Boot CommandLineRunner — triggers the Procedure Division equivalent
 * immediately on application startup, mirroring COBOL batch execution.
 */
@Slf4j
@Component
@RequiredArgsConstructor
public class JsonParseRunner implements CommandLineRunner {

    private final JsonParseService jsonParseService;

    @Override
    public void run(String... args) {
        log.info("Starting JSON Parse program");
        jsonParseService.run();
        log.info("JSON Parse program complete");
    }
}

