package com.ibm.cobolisfun.jsonparse.service;

import com.fasterxml.jackson.databind.DeserializationFeature;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import java.math.BigDecimal;

import static org.assertj.core.api.Assertions.assertThat;

class JsonParseServiceTest {

    private JsonParseService service;

    @BeforeEach
    void setUp() {
        ObjectMapper mapper = new ObjectMapper()
                .configure(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES, false);
        service = new JsonParseService(mapper);
    }

    @Test
    @DisplayName("run() completes without exception — full happy path")
    void runCompletes() {
        // Should not throw — mirrors COBOL NOT ON EXCEPTION path.
        service.run();
    }

    // ---------------------------------------------------------------
    // Picture-clause formatter unit tests
    // ---------------------------------------------------------------

    @Test
    @DisplayName("formatAccountNum: 12-digit with comma groups")
    void formatAccountNum() {
        assertThat(JsonParseService.formatAccountNum(123456789012L))
                .isEqualTo("123,456,789,012");
    }

    @Test
    @DisplayName("formatAccountNum: zero value")
    void formatAccountNumZero() {
        assertThat(JsonParseService.formatAccountNum(0L))
                .isEqualTo("000,000,000,000");
    }

    @Test
    @DisplayName("formatBalance: negative value shows CR suffix")
    void formatBalanceNegative() {
        assertThat(JsonParseService.formatBalance(new BigDecimal("-125.53")))
                .isEqualTo("$125.53CR");
    }

    @Test
    @DisplayName("formatBalance: positive value — no CR suffix")
    void formatBalancePositive() {
        assertThat(JsonParseService.formatBalance(new BigDecimal("45.00")))
                .isEqualTo("$45.00");
    }

    @Test
    @DisplayName("formatTxUid: zero-padded to 5 digits")
    void formatTxUid() {
        assertThat(JsonParseService.formatTxUid(107)).isEqualTo("00107");
        assertThat(JsonParseService.formatTxUid(1904)).isEqualTo("01904");
    }

    @Test
    @DisplayName("formatTxPrice: $ prefix with 2 decimal places")
    void formatTxPrice() {
        assertThat(JsonParseService.formatTxPrice(new BigDecimal("12.34")))
                .isEqualTo("$12.34");
        assertThat(JsonParseService.formatTxPrice(new BigDecimal("833.22")))
                .isEqualTo("$833.22");
    }
}

