spring:
  application:
    name: json-parse
  # No database wiring required — this program is a pure JSON-parse / display program.
  # PostgreSQL datasource is included below as a template should persistence be added.
  datasource:
    url: ${DB_URL:jdbc:postgresql://localhost:5432/jsonparse}
    username: ${DB_USER:jsonparse}
    password: ${DB_PASS:jsonparse}
    driver-class-name: org.postgresql.Driver
